func resourceVertexAIPublisherModelConfigEncoder(d *schema.ResourceData, meta interface{}, obj map[string]interface{}) (map[string]interface{}, error) {

	// Plugin SDK v2 returns []interface{}{nil} when all subfields of a MaxItems: 1
	// TypeList block are zero-valued, causing expand* to omit false booleans.
	if count, ok := d.Get("logging_config.#").(int); ok && count > 0 {
		cfg, _ := obj["loggingConfig"].(map[string]interface{})
		if cfg == nil {
			cfg = make(map[string]interface{})
		}
		cfg["enabled"] = d.Get("logging_config.0.enabled")
		obj["loggingConfig"] = cfg
	}
	if count, ok := d.Get("claude_feature_config.#").(int); ok && count > 0 {
		cfg, _ := obj["claudeFeatureConfig"].(map[string]interface{})
		if cfg == nil {
			cfg = make(map[string]interface{})
		}
		cfg["advancedAiEnabled"] = d.Get("claude_feature_config.0.advanced_ai_enabled")
		obj["claudeFeatureConfig"] = cfg
	}
	return map[string]interface{}{
		"publisherModelConfig": obj,
	}, nil
}

func resourceVertexAIPublisherModelConfigDecoder(d *schema.ResourceData, meta interface{}, res map[string]interface{}) (map[string]interface{}, error) {
	if cfg, ok := res["inferenceEventLoggingConfig"].(map[string]interface{}); ok {
		if state, _ := cfg["state"].(string); state == "" || state == "STATE_UNSPECIFIED" {
			delete(cfg, "state")
		}
		if len(cfg) == 0 {
			delete(res, "inferenceEventLoggingConfig")
		}
	}
	if cfg, ok := res["loggingConfig"].(map[string]interface{}); ok && len(cfg) == 0 {
		if count, ok := d.Get("logging_config.#").(int); ok && count > 0 {
			cfg["enabled"] = false
		} else {
			delete(res, "loggingConfig")
		}
	}
	if provider, _ := res["dataSharingEnabledProvider"].(string); provider == "" || provider == "MODEL_PROVIDER_UNSPECIFIED" {
		delete(res, "dataSharingEnabledProvider")
	}
	return res, nil
}
